	//로컬스토리지에서 검색어 불러오기
	function fn_GetRecentSearches(){
		const searches = localStorage.getItem(storageKey);
		return searches ? JSON.parse(searches) : [];
	}
	//검색어 리스트를 로컬스토리지에 저장
	function fn_SaveRecentSearches(searches){
		localStorage.setItem(storageKey, JSON.stringify(searches));
	}
	// 검색어 리스트를 로컬스토리지에 삭제
	function fn_RemoveRecentSearches(searches, obj){
		const key = storageKey;
		const targetValue  = searches;  // 비교할 배열
		const storedValue = localStorage.getItem(key);
		const storedArray = JSON.parse(storedValue);
		if (!Array.isArray(storedArray)) {
			return;
		}
		// targetValue가 배열에 있으면 삭제하고 다시 저장
		if (storedArray.includes(targetValue)) {
			const filteredArray = storedArray.filter(item => item !== targetValue);
			localStorage.setItem(key, JSON.stringify(filteredArray));
		}
		const parentDiv = obj.closest('div');
		if (parentDiv){
			parentDiv.remove();  // 이 부분이 삭제!
		}
	}
	//최근 검색어 UI 업데이트
	function fn_UpdateRecentSearchesUI(){
		const keyList = fn_GetRecentSearches();
		const oDiv    = $("#recentDiv");
		oDiv.find("div.word").remove();
		$.each(keyList,function(index,item){
			var sHtml = "";
			sHtml += "<div class=\"word\">";
			sHtml += "<button type=\"button\" class=\"word-btn\" onclick=\"javascript:fn_TopClickWord('"+item+"'); return false;\">";
			sHtml += "<span>"+item+"</span>";
			sHtml += "</button>"
			sHtml += "<button type=\"button\" class=\"del-btn\" onclick=\"javascript:fn_RemoveRecentSearches('"+item+"', this)\">"
			sHtml += "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"17\" viewBox=\"0 0 16 17\" fill=\"none\">";
			sHtml += "<path d=\"M4.229 4.72852L11.7715 12.271\" stroke=\"#8E8E8E\" stroke-width=\"1.6\" stroke-linecap=\"round\"/>";
			sHtml += "<path d=\"M4.229 12.2715L11.7715 4.72901\" stroke=\"#8E8E8E\" stroke-width=\"1.6\" stroke-linecap=\"round\"/>";
			sHtml += "</svg>";
			sHtml += "</button>";
			sHtml += "</div>";
			oDiv.append(sHtml);
		});
	}

	//검색어 추가
	function fn_AddSearchTerm(term){
		if (!term) return;
		let searches = fn_GetRecentSearches();
		// 중복 제거 및 리스트 업데이트
		searches = searches.filter(item => item !== term);
		searches.unshift(term);
		// 최대 개수 초과 시 마지막 검색어 제거
		if (searches.length > maxRecentSearches){
			searches.pop();
		}
		fn_SaveRecentSearches(searches);
		fn_UpdateRecentSearchesUI();
	}
