	//돋보기 버튼 이벤트
	function fn_TopTotalSearch(form,searchTp){
		//alert("fn_TopTotalSearch")
		var oForm = $("#topTotalSearchFrm");
		var query = $("#topPcQuery").val();
		//최소 글자수 제한
		if( query.trim().length < 2){
			alert("검색어는 두자리 이상 입력해 주세요.");
			return false;
		}
		var entityRegex = /&(#x?[0-9a-fA-F]+|[a-zA-Z]+);?/;
		//스크립트 차단
		if (entityRegex.test(query) || query.includes('<') || query.includes('>') || query.includes('"') || query.includes("'")){
			alert("입력하신 검색어는 콘텐츠 규칙 때문에 검색란에서 허용되지 않습니다.");
			return false;
		}
		fn_AddSearchTerm(query);
		if( searchTp == "MAIN" ){
			var deviceForm   = $(form).closest("form");
			oForm.find("input[name=query]").val(query);
			oForm.find("input[name=collection]").val("ALL");
			oForm.find("input[name=pageTp]").val("MAIN");
			oForm.find("input[name=searchTp]").val(searchTp);
			oForm.find("input[name=startDate]").val("");
			oForm.find("input[name=endDate]").val("");
			oForm.find("input[name=mode]").val("");
			oForm.find("input[name=period]").val("");
			oForm.find("input[name=reQuery]").val("");
			oForm.find("input[name=menuQuery]").val("");
			oForm.attr("action","/home/search.do").submit();
		}else if( searchTp == "DETAIL" ){
			var deviceCd     = oForm.find("input[name=deviceCd]").val();
			var deviceForm   = $(form).closest("form");
			var arrMenuQuery = new Array();
			oForm.find("input[name=query]").val(query);
			oForm.find("input[name=collection]").val("ALL");
			oForm.find("input[name=pageTp]").val("MAIN");
			oForm.find("input[name=searchTp]").val(searchTp);
			oForm.find("input[name=startDate]").val(form.find("input[name$=topStartDate]").val());
			oForm.find("input[name=endDate]").val(form.find("input[name$=topEndDate]").val());
			oForm.find("input[name=mode]").val(form.find("input[name=topMode]:checked").val());
			oForm.find("input[name=reQuery]").val(form.find("input[name=topReQuery]").val());
			oForm.find("input[name=period]").val(form.find("input[name=topPeriod]:checked").val());
			//oForm.find("input[name=menuQuery]").val(searchTp);
			$.each(deviceForm.find("input[name=topMenuQuery]:checked"),function(index,item){
				arrMenuQuery.push($(this).val());
			});
			oForm.find("input[name=menuQuery]").val(arrMenuQuery.join());
			//return false;
			oForm.attr("action","/home/search.do").submit();
		}
	}
