				$(obj).closest(".input-checkbox-box").find("input[name*=topMenuNoAll]").prop("checked",true);
			}else{
				$(obj).closest(".input-checkbox-box").find("input[name*=topMenuNoAll]").prop("checked",false);
			}
		}
	}
	//기간 클릭 이벤트
	function fn_TopClickPeriod(obj,arg){
		var oForm     = $(obj).closest("form");
		var nowDate   = new Date().toISOString().substring(0,10);
		var startDate = "";
		var endDate   = "";
		if( arg == "ALL" ){
			startDate = "";
			endDate   = "";
		}else{
			endDate = nowDate;
			if( arg == "1M" )  		startDate = GU.addMonth(nowDate,-1);
			else if( arg == "3M" )  startDate = GU.addMonth(nowDate,-3);
			else if( arg == "6M" )  startDate = GU.addMonth(nowDate,-6);
			else if( arg == "1Y" )  startDate = GU.addMonth(nowDate,-12);
		}
		oForm.find("input[name$=StartDate]").val(startDate);
		oForm.find("input[name$=EndDate]").val(endDate);
		oForm.find("input[name$=StartDate]").addClass("has-value");
		oForm.find("input[name$=EndDate]").addClass("has-value");
	}
	//초기화 버튼 클릭
	function fn_TopClickReset(obj){
		var oForm = $(obj).closest("form");
		//$("#topPcQuery").val("");
		$("input[name=topMode]").eq(0).prop("checked",true);
		$("#topReQuery").val("");
		$("#topMenuNoAll").prop("checked",false);
		$("input[name=topMenuQuery]").prop("checked",false);
		$("input[name=topPeriod]").prop("checked",false);
		$("input[name=topPeriod]").eq(0).prop("checked",true);
