		reset_moveTab(oForm);
	}
	// 라디오 버튼 상태 초기화 후 스타일 재적용
	function reset_moveTab(oForm){
		// 데이터 속성을 가진 요소를 선택
		var periodTabWrap = oForm.find('[data-tab-action="glider"]').eq(0); // 첫 번째 요소를 가져옴
		if (!periodTabWrap.length) return;
		// glider 내부의 모든 radio 버튼을 선택
		var radioButtons = periodTabWrap.find('input[type="radio"]');
		if (!radioButtons.length) return;
		// 모든 radio 버튼의 checked 상태를 초기화
		radioButtons.each(function () {$(this).prop('checked', false);$(this).removeAttr('checked');});
		// 제일 첫 번째 radio 버튼에 checked 설정
		var firstRadio = radioButtons.eq(0);
		firstRadio.prop('checked',true);
